Q: Content not displaying in div using webpack A: <p>npm install --save-dev style-loader css-loader</p>
<pre><code>const path = require(&quot;path&quot;);

module.exports = {
  mode: &quot;development&quot;,
  entry: &quot;./src/index.js&quot;,
  output: {
    filename: &quot;main.js&quot;,
    path: path.resolve(__dirname, &quot;dist&quot;),
    clean: true,
  },
  module: {
    rules: [
      {
        test: /\.css$/i,
        use: [&quot;style-loader&quot;, &quot;css-loader&quot;],
      },
      {
        test: /\.(png|jpg|jpeg|gif|svg)$/i,
        type: &quot;asset/resource&quot;,
      },
    ],
  },
};
</code></pre>
